WITH scored AS (SELECT id, product_id, last_restock, AVG(quantity) OVER (PARTITION BY DATE_TRUNC('WEEK', last_restock), store_id ORDER BY quantity, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS quantity_avg_6, CUME_DIST() OVER (PARTITION BY product_id, store_id ORDER BY quantity DESC NULLS LAST) AS quantity_cume_dist, AVG(quantity) OVER w_ordered AS quantity_avg_6_2 FROM inventory WINDOW w_ordered AS (PARTITION BY store_id ORDER BY last_restock, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)), joined AS (SELECT a.*, b.launch_date, b.cost, b.stock_qty FROM scored a LEFT JOIN products b ON a.product_id = b.id), ranked AS (SELECT id, product_id, quantity_cume_dist, quantity_avg_6_2, cost, stock_qty FROM joined QUALIFY ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY last_restock, id) = 1), with_windows AS (SELECT id, product_id, cost, stock_qty, LEAD(stock_qty) OVER w_grp AS next_stock_qty, LAG(quantity_avg_6_2) OVER w_grp AS prev_quantity_avg_6_2, ROW_NUMBER() OVER w_grp AS seq_no, LAST_VALUE(cost, TRUE) OVER w_part AS last_known_cost FROM ranked WINDOW w_grp AS (PARTITION BY product_id ORDER BY quantity_avg_6_2, id), w_part AS (PARTITION BY product_id ORDER BY quantity_cume_dist, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), enriched AS (SELECT src.id, src.product_id, src.seq_no, b.cost AS product_cost FROM with_windows src LEFT JOIN products b ON src.product_id = b.id) SELECT CASE WHEN seq_no >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END AS seq_no_tier, CASE WHEN product_cost >= 780 THEN 'HIGH' ELSE 'LOW' END AS product_cost_tier, COUNT(DISTINCT id) AS distinct_ids, APPROX_PERCENTILE(product_cost, 0.5) AS product_cost_p50 FROM enriched GROUP BY GROUPING SETS ((CASE WHEN seq_no >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN product_cost >= 780 THEN 'HIGH' ELSE 'LOW' END), (CASE WHEN seq_no >= 8 THEN 'PREMIUM' ELSE 'STANDARD' END), ()) HAVING product_cost_p50 > 0;
